    async fn transitive_groups_cycles_limits_and_removal(pool: PgPool) -> sqlx::Result<()> {
        let ids: Vec<_> = (1..=4).map(uuid::Uuid::from_u128).collect();
        for (id, name) in ids.iter().zip(["Alpha", "Beta", "Gamma", "Alpha separate"]) {
            sqlx::query!("INSERT INTO exposed.funders (id, funder_name) VALUES ($1, $2)", id, name)
                .execute(&pool).await?;
        }
        for (id, alias) in [(ids[0], "Bridge one"), (ids[1], " BRIDGE\tONE "),
            (ids[1], "Bridge two"), (ids[2], "Bridge two"), (ids[2], "ALPHA")] {
            sqlx::query!("INSERT INTO exposed.funder_aliases (funder_id, funder_alias) VALUES ($1, $2)", id, alias)
                .execute(&pool).await?;
        }
        let db = ExposedDatabase::from(pool.clone());
        let request = |term: &str, limit| EntitySearchRequest::new_with_strictness(term.into(), limit, 1.0).unwrap();
        let groups = sqlx::query!("SELECT funder_id AS \"id!\", group_id AS \"group_id!\" FROM exposed.funder_alias_groups ORDER BY funder_id")
            .fetch_all(&pool).await?;
        assert_eq!(groups.len(), 4);
        assert!(groups[..3].iter().all(|row| row.group_id == ids[0]));
        assert_eq!(groups[3].group_id, ids[3]);
        let matched = db.get_funders_by_text_search_score(&request("Gamma", 2)).await.unwrap().matches;
        assert_eq!(matched.len(), 1);
        assert_eq!(matched[0].0.funder().id().value(), ids[0]);
        assert_eq!(matched[0].0.funder().name(), "Alpha");
        assert_eq!(matched[0].0.source(), &crate::domain::models::entity_search::SearchMatchSource::Alias { name: "Gamma".into() });
        let limited = db.get_funders_by_text_search_score(&request("Alpha", 2)).await.unwrap().matches;
        assert_eq!(limited.len(), 2);
        assert_eq!(limited[1].0.funder().id().value(), ids[3]);
        sqlx::query!("DELETE FROM exposed.funder_aliases WHERE funder_id = $1", ids[2]).execute(&pool).await?;
        let groups = sqlx::query!("SELECT group_id AS \"group_id!\" FROM exposed.funder_alias_groups WHERE funder_id = $1", ids[2]).fetch_one(&pool).await?;
        assert_eq!(groups.group_id, ids[2]);
        assert_eq!(db.get_funders_by_text_search_score(&request("Gamma", 2)).await.unwrap().matches[0].0.funder().id().value(), ids[2]);
        Ok(())
    }

    #[sqlx::test(migrations = "../db/migrations")]
